				udc_obj.getValue_1 = function(){

				};

				/**
				 * Function description...
				 * @date 2019. 06. 20
				 * @memberOf udc_obj
				 * @param 
				 * @returns  
				 * @author mo
				 * @example
				 * @since
				*/ 
				udc_obj.onTrigger1 = function(){
				    console.log("udc_obj.onTrigger1");
                    var udcID = udc_obj.id;

                    //[WEFF-598 / WSQ-3954 / WSQ-4293 가이드]
                    //1) config.js strictMode(@value="true", @id="mf") 환경에서는
                    //   main 페이지의 scwin 이 window.mf_scwin 으로 등록된다.
                    //2) config.js wframe.scope(@value="true") 환경에서는 wframe 내부에
                    //   별도의 scwin 이 생성되므로, UDC 클로저에서 참조하는 scwin 은
                    //   wframe-local 객체이며 main 페이지의 함수에 접근할 수 없다.
                    //=> 외부(main) 함수는 아래처럼 글로벌 scope variable 로 접근한다.
                    var outerScwin = window.mf_scwin || window.scwin;    //strictMode @id="mf"
                    var func = outerScwin && outerScwin.outter_wframe;
                    if(typeof func === "function") {
                        func.call(outerScwin, udcID);
                    } else {
                        alert("mf_scwin.outter_wframe is not a function");
                    }
				};

				/**
				 * Function description...
				 * @date 2019. 06. 20
				 * @memberOf udc_obj
				 * @param 
				 * @returns  
				 * @author mo
				 * @example
				 * @since
				*/ 
				udc_obj.onTrigger2 = function(){
				    console.log("udc_obj.onTrigger2");
                    var udcID = udc_obj.id;

                    //문자열로 함수를 지정하는 패턴도 동일하게 strictMode prefix 를 반영해야 한다.
                    //strictMode @id="mf" 이므로 글로벌 scope variable 명은 "mf_scwin" 이다.
                    var _win = window || parent;
                    var scopeVar = _win.mf_scwin ? "mf_scwin" : "scwin";

                    var funcStr = scopeVar + ".outter_wframe";
                    var objArr = funcStr.split(".");

                    var callbackFn = _win[objArr[0]] && _win[objArr[0]][objArr[1]];
                    if(typeof callbackFn === "function") {
                        callbackFn.call(_win[objArr[0]], udcID);
                    } else {
                        alert(funcStr + " is not a function");
                    }
				};
